import React, { useEffect, useRef, useState } from "react";
import { motion, useInView } from "framer-motion";
import { STATS } from "./Content";

function Counter({ to, suffix, index }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });
  const started = useRef(false);

  useEffect(() => {
    if (isInView && !started.current) {
      started.current = true;
      const duration = 1800;
      const start = performance.now();
      const tick = (now) => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setVal(Math.round(to * eased));
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }
  }, [isInView, to]);

  return (
    <motion.span
      ref={ref}
      className="serif"
      style={{ fontSize: 56, color: "#d4af37", fontWeight: 400 }}
      initial={{ opacity: 0, scale: 0.5 }}
      animate={isInView ? { opacity: 1, scale: 1 } : {}}
      transition={{ delay: index * 0.1, duration: 0.5 }}
    >
      {val.toLocaleString()}{suffix}
    </motion.span>
  );
}

// Stat card animation
const statCardVariants = {
  hidden: { opacity: 0, y: 30 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    transition: { delay: i * 0.15, duration: 0.5, ease: "easeOut" }
  }),
  hover: {
    y: -5,
    boxShadow: "0 12px 30px rgba(212,175,55,0.25)",
    transition: { duration: 0.2 }
  }
};

export default function About() {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });

  return (
    <section id="about" className="relative px-6 md:px-12 lg:px-24 py-28 md:py-36" style={{ background: "#ffffff" }}>
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
        <motion.div
          className="lg:col-span-5"
          initial={{ opacity: 0, x: -50 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true, margin: "-100px" }}
          transition={{ duration: 0.7, ease: "easeOut" }}
        >
          <div className="overline mb-4">The Legacy</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 400, color: "#1a080a" }}>
            A fabric house from <span style={{ color: "#d4af37", fontStyle: "italic" }}>Ludhiana,</span> adorning India's grandest celebrations.
          </h2>
        </motion.div>

        <div className="lg:col-span-6 lg:col-start-7" ref={ref}>
          <motion.p
            className="text-base md:text-lg"
            style={{ color: "rgba(26,8,10,0.75)", lineHeight: 1.7, maxWidth: 580 }}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.1 }}
          >
            For over a decade, D SAJAWAT has been the quiet hand behind some of the country's most exquisite wedding venues. We source, finish and supply premium fabrics - drapes, covers, sashes, florals.
          </motion.p>

          <motion.p
            className="mt-5 text-base md:text-lg"
            style={{ color: "rgba(26,8,10,0.6)", lineHeight: 1.7, maxWidth: 580 }}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.6, delay: 0.2 }}
          >
            From a single roll to a banquet's worth - we deliver across India, on time, in finish.
          </motion.p>

          <motion.div
            className="mt-10 grid grid-cols-2 gap-6"
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: "-50px" }}
            variants={{
              hidden: { opacity: 0 },
              visible: { opacity: 1, transition: { staggerChildren: 0.15, delayChildren: 0.3 } }
            }}
          >
            {STATS.map((s, i) => (
              <motion.div
                key={s.label}
                className="p-6 rounded-lg text-center"
                style={{ background: "linear-gradient(135deg, #fffdf5 0%, #fff9ed 100%)", border: "1px solid rgba(212,175,55,0.3)", boxShadow: "0 4px 20px rgba(212,175,55,0.1)" }}
                custom={i}
                variants={statCardVariants}
                whileHover="hover"
              >
                <Counter to={s.value} suffix={s.suffix} index={i} />
                <motion.div
                  className="mt-2 overline"
                  style={{ color: "rgba(26,8,10,0.6)" }}
                  initial={{ opacity: 0 }}
                  whileInView={{ opacity: 1 }}
                  viewport={{ once: true }}
                  transition={{ delay: 0.5 + i * 0.1 }}
                >
                  {s.label}
                </motion.div>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
